{"code":"import math

def triangular_sum(n):
    # Generate a list of triangular numbers
    triangular_numbers = []
    limit = int(math.sqrt(n)) + 1
    for i in range(1, limit):
        triangular_numbers.append(i * (i + 1) // 2)

    # Check if the sum of squares of two consecutive triangular numbers equals n
    for i in range(len(triangular_numbers) - 1):
        if triangular_numbers[i] ** 2 + triangular_numbers[i+1] ** 2 == n:
            return True

    return False"}

