{"code":"def solve(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def has_prime_digits(num):
        prime_digits = [2, 3, 5, 7]
        for digit in str(num):
            if int(digit) in prime_digits:
                return True
        return False

    array = []
    num = 1
    while len(array) <= n:
        if not is_prime(num) and not has_prime_digits(num):
            array.append(num)
        num += 1

    return array[n]"}

