{"code":"def get_strings(city):
    counts = {}
    for char in city:
        if char.isalpha():
            char = char.lower()
            if char in counts:
                counts[char] += 1
            else:
                counts[char] = 1

    output = []
    for char, count in counts.items():
        output.append(char + ":" + "*" * count)

    return ",".join(output)"}

