{"code":"from typing import List

def reduce_pyramid(base: List[int]) -> int:
    while len(base) > 1:
        new_base = []
        for i in range(len(base) - 1):
            new_base.append(base[i] + base[i+1])
        base = new_base
    return base[0]"}

{"code":"def adjacent_element_product(array):
    max_product = float('-inf')
    for i in range(len(array) - 1):
        product = array[i] * array[i+1]
        if product > max_product:
            max_product = product
    return max_product"}

{"code":"def or_arrays(a, b, filler=0):
    result = []
    length = max(len(a), len(b))
    for i in range(length):
        if i < len(a) and i < len(b):
            result.append(a[i] | b[i])
        elif i < len(a):
            result.append(a[i] | filler)
        else:
            result.append(b[i] | filler)
    return result"}

